package cn.xiaoyanjiu.ff14chat;
import android.os.*;import android.webkit.WebView;import org.json.*;import java.io.*;import javax.net.ssl.HttpsURLConnection;import java.util.concurrent.atomic.*;
/** One pinned TLS stream; latest frame wins instead of queuing pictures on the UI thread. */
final class GlamourFrameStream {
 final MainActivity activity;final WebView web;final Handler ui=new Handler(Looper.getMainLooper());final AtomicInteger generation=new AtomicInteger();final AtomicReference<String> latest=new AtomicReference<>();final AtomicBoolean scheduled=new AtomicBoolean();volatile HttpsURLConnection connection;
 GlamourFrameStream(MainActivity a,WebView w){activity=a;web=w;}
 void stop(){generation.incrementAndGet();latest.set(null);scheduled.set(false);HttpsURLConnection c=connection;connection=null;if(c!=null)new Thread(c::disconnect,"Glamour-preview-close").start();}
 void start(String id){stop();int ticket=generation.get();new Thread(()->{int failures=0;while(ticket==generation.get()){HttpsURLConnection c=null;try{if(!ChatService.pageEnabled("glamour"))throw new IOException("服务端已停用该页面");c=Transport.openGlamour(activity,id);if(ticket!=generation.get())return;connection=c;if(c.getResponseCode()!=200)throw new IOException("预览连接暂不可用（HTTP "+c.getResponseCode()+"）");try(DataInputStream in=new DataInputStream(new BufferedInputStream(c.getInputStream(),65536))){while(ticket==generation.get()){byte[] bytes=GlamourFramePacket.read(in);if(ticket!=generation.get())return;String json=new String(bytes,"UTF-8");JSONObject frame=new JSONObject(json);frame.put("presetId",id);failures=0;latest.set(frame.toString());deliver(ticket);}}}catch(Exception e){if(ticket==generation.get())ui.post(()->{if(ticket==generation.get())web.evaluateJavascript("glamourStreamError("+JSONObject.quote("预览连接中断，正在恢复…")+")",null);});}finally{if(c!=null)c.disconnect();if(connection==c)connection=null;}if(ticket!=generation.get())return;try{Thread.sleep(Math.min(4000,250L<<Math.min(failures++,4)));}catch(InterruptedException e){return;}}},"Glamour-preview-stream").start();}
 void deliver(int ticket){if(!scheduled.compareAndSet(false,true))return;ui.post(()->{if(ticket!=generation.get())return;String json=latest.getAndSet(null);if(json==null){scheduled.set(false);return;}web.evaluateJavascript("glamourStreamFrame("+json+")",result->{if(ticket!=generation.get())return;scheduled.set(false);if(latest.get()!=null)deliver(generation.get());});});}
}
